tool_use_result.originalFile:
import { ok, fail } from './result.js';
import { getCustomer, normalizeId, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';
import { lineTotal, lineDiscount, lineVat, invoiceTotals } from './totals.js';

export { lineTotal, lineDiscount, lineVat, invoiceTotals } from './totals.js';

/**
 * Validate discount percent is a number between 0 and 100.
 * @param {unknown} value
 * @returns {boolean}
 */
function isValidDiscountPercent(value) {
  return typeof value === 'number' && value >= 0 && value <= 100;
}

/**
 * Calculate the due date based on payment terms and issue date.
 * @param {string} issueDate - YYYY-MM-DD format
 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
 * @returns {string} - Due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    const [yearStr, monthStr] = issueDate.split('-');
    const year = Number(yearStr);
    const month = Number(monthStr);

    let nextMonthDate;
    if (month === 12) {
      nextMonthDate = new Date(Date.UTC(year + 1, 0, 1));
    } else {
      nextMonthDate = new Date(Date.UTC(year, month, 1));
    }

    nextMonthDate.setUTCDate(0);
    const y = nextMonthDate.getUTCFullYear();
    const m = nextMonthDate.getUTCMonth() + 1;
    const d = nextMonthDate.getUTCDate();

    return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  }
}

/**
 * Calculate the total for a single invoice line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const discount = roundCents(lineTotal(line) * discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate VAT for a single line (on the amount after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }} line
 * @returns {number}
 */
export function lineVat(line) {
  const vatRate = line.vatRate ?? 0;
  const amountAfterDiscount = Math.max(0, lineTotal(line) - lineDiscount(line));
  const vat = roundCents(amountAfterDiscount * vatRate / 100);
  return Math.max(0, vat);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: unknown, discountPercent?: unknown }>, terms?: unknown }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms?: string, dueDate?: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate issue date format and validity
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate terms
  const validTerms = ['NET14', 'NET30', 'EOM'];
  if (!validTerms.includes(terms)) return fail('TERMS_INVALID');

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Build enriched lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discountPercent if provided
    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product from catalogue
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;

    // Determine discount: use explicit value if provided, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined
      ? line.discountPercent
      : TIER_DISCOUNTS[customerResult.value.tier];

    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  const dueDate = calculateDueDate(issueDate, terms);

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms,
    dueDate,
  };

  return ok(invoice);
}

/**
 * Add or update a line on an invoice.
 * @param {{ customerId: string, status: string, lines: Array<{ sku: string, qty: number, name: string, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: unknown, discountPercent?: unknown }} params
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discountPercent if provided
  if (discountPercent !== undefined && !isValidDiscountPercent(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  // Get product from catalogue
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Get customer to determine tier discount for new lines
  const customerResult = getCustomer(invoice.customerId);
  const tierDiscount = customerResult.ok ? TIER_DISCOUNTS[customerResult.value.tier] : 0;

  // Create new invoice with updated lines
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex !== -1) {
    // Update existing line
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
      ...(discountPercent !== undefined && { discountPercent }),
    };
  } else {
    // Add new line
    const lineDiscountPercent = discountPercent !== undefined ? discountPercent : tierDiscount;
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: lineDiscountPercent,
    });
  }

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find line with SKU
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check that removing it won't leave the invoice with no lines
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new invoice without the line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Issue an invoice (assign a number and change status to 'issued').
 * @param {{ status: string, issueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - Invoice numbers already in use
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Generate next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  // Create new invoice with number and issued status
  const newInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };

  return ok(newInvoice);
}

/**
 * Apply a voucher to an invoice.
 * @param {{ status: string, voucher?: any, lines: Array }} invoice
 * @param {{ code: string, amount: unknown }} params
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check invoice doesn't already have a voucher
  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  // Validate amount is a positive integer
  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');

  // Create new invoice with voucher
  const newInvoice = {
    ...invoice,
    voucher: { code, amount },
  };

  return ok(newInvoice);
}

